from collections import deque


def shortest_alternating_paths(n, red_edges, blue_edges):
    graph = [[[] for _ in range(n)], [[] for _ in range(n)]]
    for u, v in red_edges:
        graph[0][u].append(v)
    for u, v in blue_edges:
        graph[1][u].append(v)

    dist = {}
    queue = deque([(0, 0, 0), (0, 1, 0)])
    visited = {(0, 0), (0, 1)}

    while queue:
        node, color, d = queue.popleft()
        if node not in dist:
            dist[node] = d
        next_color = 1 - color
        for nb in graph[next_color][node]:
            if (nb, next_color) not in visited:
                visited.add((nb, next_color))
                queue.append((nb, next_color, d + 1))

    return [dist.get(i, -1) for i in range(n)]


if __name__ == "__main__":
    print(shortest_alternating_paths(3, [[0, 1]], [[1, 2]]))
    print(shortest_alternating_paths(3, [[0, 1]], [[2, 1]]))

