import java.util.*;

public class Main {
    static int[] shortestAlternatingPaths(int n, int[][] redEdges, int[][] blueEdges) {
        List<List<Integer>>[] graph = new List[2];
        graph[0] = new ArrayList<>();
        graph[1] = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph[0].add(new ArrayList<>());
            graph[1].add(new ArrayList<>());
        }
        for (int[] e : redEdges) graph[0].get(e[0]).add(e[1]);
        for (int[] e : blueEdges) graph[1].get(e[0]).add(e[1]);

        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[0] = 0;
        boolean[][] visited = new boolean[n][2];
        visited[0][0] = true;
        visited[0][1] = true;
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{0, 0, 0});
        queue.add(new int[]{0, 1, 0});

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int node = cur[0], color = cur[1], d = cur[2];
            int nextColor = 1 - color;
            for (int nb : graph[nextColor].get(node)) {
                if (!visited[nb][nextColor]) {
                    visited[nb][nextColor] = true;
                    if (dist[nb] == -1) dist[nb] = d + 1;
                    queue.add(new int[]{nb, nextColor, d + 1});
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(shortestAlternatingPaths(3, new int[][]{{0, 1}}, new int[][]{{1, 2}})));
        System.out.println(Arrays.toString(shortestAlternatingPaths(3, new int[][]{{0, 1}}, new int[][]{{2, 1}})));
    }
}

