def shortest_alternating_paths(n, red_edges, blue_edges):
    graph = [[[] for _ in range(n)], [[] for _ in range(n)]]
    for u, v in red_edges:
        graph[0][u].append(v)
    for u, v in blue_edges:
        graph[1][u].append(v)

    dist = [-1] * n
    dist[0] = 0
    visited = [[False, False] for _ in range(n)]
    visited[0][0] = True
    visited[0][1] = True
    queue = deque([(0, 0), (0, 1)])
    steps = 0

    while queue:
        steps += 1
        for _ in range(len(queue)):
            node, color = queue.popleft()
            for nb in graph[color][node]:
                if not visited[nb][color]:
                    visited[nb][color] = True
                    if dist[nb] == -1:
                        dist[nb] = steps
                    queue.append((nb, 1 - color))

    return dist


if __name__ == "__main__":
    print(shortest_alternating_paths(3, [[0, 1]], [[1, 2]]))
    print(shortest_alternating_paths(3, [[0, 1]], [[2, 1]]))

